package com.mt8163.tools.ui;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.view.LayoutInflater;import android.view.View;import android.widget.FrameLayout;import android.widget.ListView;import com.mt8163.tools.MainApplication;import com.mt8163.tools.R;import com.mt8163.tools.core.ModuleContract;import com.mt8163.tools.core.ModuleRegistry;import com.mt8163.tools.core.PreferencesManager;import com.mt8163.tools.modules.events.EventManager;import com.mt8163.tools.modules.events.EventsModuleView;import com.mt8163.tools.modules.voltage.VoltageModuleView;import com.mt8163.tools.modules.voltage.VoltageSettingsStore;import java.util.List;
public final class MainActivity extends Activity {
 private ModuleRegistry registry;private PreferencesManager prefs;private List<ModuleContract> modules;private SidebarAdapter adapter;private FrameLayout header,content;private View overlay;private int selected;
 @Override protected void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_main);MainApplication app=(MainApplication)getApplication();registry=app.getModuleRegistry();prefs=app.getPreferencesManager();modules=registry.getModules();ListView list=findViewById(R.id.sidebar_list);header=findViewById(R.id.header_container);content=findViewById(R.id.content_container);overlay=findViewById(R.id.disabled_overlay);adapter=new SidebarAdapter(this,modules);list.setAdapter(adapter);selected=modules.size()-1;list.setOnItemClickListener((p,v,pos,id)->showModule(pos));showModule(selected);}
 private void showModule(int position){if(position<0||position>=modules.size())return;selected=position;ModuleContract module=modules.get(position);adapter.setSelectedPosition(position);header.removeAllViews();ModuleHeaderView hv=new ModuleHeaderView(this);hv.bind(module,enabled->{registry.saveState(module,prefs);if("events".equals(module.getId())){EventManager em=EventManager.get(this);if(enabled){em.setEnabled(true);em.logLifecycle("moduleEnabled","Events module enabled");}else{em.logLifecycle("moduleDisabled","Events module disabled");em.setEnabled(false);}}if("voltage".equals(module.getId()))VoltageSettingsStore.publish(this);adapter.notifyDataSetChanged();if(enabled&&"events".equals(module.getId()))showModule(selected);else updateState();});header.addView(hv);content.removeAllViews();if("events".equals(module.getId())){if(module.isEnabled())content.addView(EventsModuleView.create(this));}else{View view=LayoutInflater.from(this).inflate(module.getLayoutRes(),content,false);content.addView(view);if("voltage".equals(module.getId()))VoltageModuleView.bind(view,this);}updateState();}
 private void updateState(){boolean enabled=modules.get(selected).isEnabled();content.setEnabled(enabled);content.setAlpha(enabled?1f:0.32f);overlay.setVisibility(enabled?View.GONE:View.VISIBLE);}
 @Override protected void onDestroy(){EventsModuleView.destroy();super.onDestroy();}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);EventsModuleView.onActivityResult(requestCode,resultCode,data);}
}